H='أَقْرَأُ السُّؤَالَ، ثُمَّ أُظَلِّلُ حَرْفَ الإِجَابَةِ الصَّحِيحَةِ فِي وَرَقَةِ الإِجَابَةِ'
SAW='صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ'
DG='٠١٢٣٤٥٦٧٨٩'; ar=lambda x:''.join(DG[int(c)] if c.isdigit() else ('٫' if c=='.' else c) for c in str(x))
def W(t,rows): return {"type":"words","title":t,"hint":H,"rows":rows}
def TF(rows): return {"type":"tf","title":"صَوَابٌ أَمْ خَطَأٌ؟","rows":rows}
def surah(name,ayat,cls="two tight",start=1,title="أَحْفَظُ السُّورَةَ",bas=True):
  ay=''.join((f'<p class="ay">{a.rsplit(" ",1)[0]} <span class="nw">{a.rsplit(" ",1)[1]}&nbsp;<i>{ar(k+start)}</i></span></p>' if ' ' in a else f'<p class="ay"><span class="nw">{a}&nbsp;<i>{ar(k+start)}</i></span></p>') for k,a in enumerate(ayat))
  b='<p class="bas">بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ</p>' if bas else ''
  return {"type":"raw","title":title,"html":f'<div class="surah fat {cls}"><h3>{name}</h3>{b}<div class="cols">{ay}</div></div>'}
