r=[]
for amt,ds,p in [(4000,[400,40],0),(10000,[1000,25],1),(20000,[200,2000],2),(8000,[80,800],0)]:
  z=D(amt)*D('0.025'); assert z==int(z) and int(z) not in ds
  U_=lambda n: ar(n)+(' رِيَالًا' if 11<=n%100<=99 else ' رِيَالٍ')
  o=[U_(x) for x in ds]
  c=U_(int(z))
  o.insert(p,c); r.append([f'مَالٌ مِقْدَارُهُ {ar(amt)} رِيَالٍ مَضَى عَلَيْهِ حَوْلٌ، زَكَاتُهُ = ...',o])
assert D(4000)*D('0.025')==100
